+
+function orNull(value) {
+    return value || null;
+}
+
+function orZero(value) {
+    return value || 0;
+}
+
+function orEmpty(value) {
+    return value || '';
+}
+
+function hasLabel(labels, label) {
+    return (labels || []).indexOf(label) !== -1;
+}
+
 /**
