        var h = loadForPrSearch(null);
        var pr = { number: null, url: null, branch: null };

        h.mod.searchMissingPRNumber({}, {}, 'PROJ-1', pr, { owner: 'a', repo: 'b' });

        assert.equal(pr.number, null);
        assert.equal(h.searchCalls.length, 1);
    });
