    console.log('✅ Posted inline comment on ' + plan.effectivePath + ':' + plan.effectiveLine +
        (inlineCommentMapped(plan, filePath, inlineComment) ?
            ' (mapped from ' + filePath + ':' + inlineComment.line + ')' : ''));
